  importPanel.remove();toolbar.insertAdjacentHTML('beforeend',`<button class="secondary compact collapse-trigger" onclick="toggleConfigBlock(this,'#assignment-groups-list')">展开被评价人名单</button>`);groups.id='assignment-groups-list';groups.classList.add('config-collapsible','collapsed');
  relationshipSection.append(form,toolbar,groups);content.prepend(reviewerSection,relationshipSection);
  form.insertAdjacentHTML('beforeend','<div id="assignment-weight-notice" class="assignment-weight-notice form-notice" role="alert" hidden></div>');
  updateAssignmentWeightNotice();
