function updateAssignmentWeightNotice(notify=false){
  const id=document.querySelector('#assignment-submission').value;
  const blocked=window.assignmentData.submissions.find(s=>s.id===id)?.reviewWeightsReady===false;
  const notice=document.querySelector('#assignment-weight-notice');
  notice.hidden=!blocked;
  notice.innerHTML=blocked?`请先完整配置子维度权重（合计100%），再进行评委配置。 <button type="button" class="secondary compact" onclick="openMatrixWeights('${id}',renderAssignments)">配置子维度权重</button>`:'';
  document.querySelectorAll('#assignment-reviewer,#assignment-weight,.assignment-form button[onclick="saveAssignment()"]').forEach(el=>el.disabled=blocked);
  if(blocked&&notify)toast('请先配置子维度权重，再进行评委配置');
  return !blocked;
}
async function openAssignmentConfiguration(submissionId){
  try{
    const detail=await api(`/api/submissions/${submissionId}`);
    if(!reviewWeightsReady(detail)){
      toast('请先配置子维度权重，再进行评委配置');
      await openMatrixWeights(submissionId);
      return;
    }
    selectedAssignmentSubmissionId=submissionId;setView('assignments');
  }catch(e){toast(e.message)}
}
function toggleConfigBlock(button,selector){const block=document.querySelector(selector),opening=block.classList.contains('collapsed');block.classList.toggle('collapsed',!opening);button.textContent=opening?(selector.includes('reviewer')?'收起名单':'收起被评价人名单'):(selector.includes('reviewer')?'展开名单':'展开被评价人名单')}
