async function removeReviewer(id,name,usage){const warning=usage?`\n该评委已有 ${usage} 条评价关系，相关草稿和评分也会一并删除。`:'';if(!confirm(`确定删除评委“${name}”吗？${warning}\n此操作不可撤销。`))return;try{await api(`/api/admin/reviewers/${id}/delete`,{method:'POST',body:'{}'});toast('评委已删除');renderAssignments()}catch(e){toast(e.message)}}
function downloadAssignmentTemplate(){window.location.href='/api/admin/assignments/import-template'}
async function importAssignmentExcel(file){if(!file)return;try{const response=await fetch('/api/admin/assignments/import',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file}),result=await response.json();if(!response.ok)throw new Error((result.errors||[result.error]).join('\n'));toast(`导入完成：新增 ${result.created} 条，更新 ${result.updated} 条`);renderAssignments()}catch(e){toast(e.message)}finally{const input=document.querySelector('#assignment-import-file');if(input)input.value=''}}
function editReviewerAccessCode(reviewerId,reviewerName){const mask=document.createElement('div');mask.className='drawer-mask';mask.innerHTML=`<aside class="drawer assignment-edit-drawer"><div class="drawer-head"><div><div class="eyebrow">身份隔离</div><h2>设置 ${esc(reviewerName)} 的访问码</h2></div><button class="close" onclick="this.closest('.drawer-mask').remove()">×</button></div><label class="edit-field"><span>4 至 8 位数字访问码</span><input id="reviewer-access-code" type="password" inputmode="numeric" maxlength="8" placeholder="例如 2608"/></label><div class="assignment-edit-note">系统仅保存加密摘要，管理员以后只能重置，不能查看原码。</div><div class="drawer-actions"><button class="secondary" onclick="this.closest('.drawer-mask').remove()">取消</button><button class="primary" onclick="saveReviewerAccessCode('${reviewerId}',this)">保存访问码</button></div></aside>`;document.body.append(mask);mask.querySelector('input').focus()}
async function saveReviewerAccessCode(reviewerId,button){const mask=button.closest('.drawer-mask'),code=mask.querySelector('#reviewer-access-code').value;if(!/^\d{4,8}$/.test(code))return toast('访问码必须是 4 至 8 位数字');try{await api(`/api/admin/reviewers/${reviewerId}/access-code`,{method:'POST',body:JSON.stringify({code})});mask.remove();toast('访问码已设置');renderAssignments()}catch(e){toast(e.message)}}
function editAssignment(submissionId,reviewerName,weight){selectedAssignmentSubmissionId=submissionId;document.querySelector('#assignment-submission').value=submissionId;document.querySelector('#assignment-reviewer').value=reviewerName;document.querySelector('#assignment-weight').value=weight;document.querySelector('.assignment-form').scrollIntoView({behavior:'smooth',block:'start'})}
function editAssignmentById(id){const item=window.assignmentData.assignments.find(x=>x.id===id);if(!item)return;if(window.assignmentData.submissions.find(s=>s.id===item.submission_id)?.reviewWeightsReady===false)return openAssignmentConfiguration(item.submission_id);const weightPercent=Number((Number(item.weight)*100).toFixed(2));const mask=document.createElement('div');mask.className='drawer-mask';mask.onclick=e=>{if(e.target===mask)mask.remove()};mask.innerHTML=`<aside class="drawer assignment-edit-drawer"><div class="drawer-head"><div><div class="eyebrow">评审配置</div><h2>修改评价人及权重</h2></div><button class="close" onclick="this.closest('.drawer-mask').remove()">×</button></div><div class="assignment-edit-context"><span>被评价人</span><strong>${esc(item.submission_name)}</strong><small>已提交的原始评分不会因修改权重而变化</small></div><label class="edit-field"><span>评价人姓名</span><input id="edit-assignment-reviewer" value="${esc(item.reviewer_name)}"/></label><label class="edit-field"><span>汇总权重</span><div class="percent-input"><input id="edit-assignment-weight" type="number" min="1" max="100" step="1" value="${weightPercent}"/><span>%</span></div></label><div class="assignment-edit-note">保存后，结果看板和 Excel 导出会立即按照新权重重新计算；评委逐项评分、定性评价和提交状态均会保留。</div><div class="drawer-actions"><button class="secondary" onclick="this.closest('.drawer-mask').remove()">取消</button><button class="primary" onclick="saveAssignmentEdit('${id}',this)">保存修改</button></div></aside>`;document.body.append(mask);mask.querySelector('#edit-assignment-weight').focus()}
async function saveAssignmentEdit(id,button){const mask=button.closest('.drawer-mask'),reviewerName=mask.querySelector('#edit-assignment-reviewer').value.trim(),weightPercent=Number(mask.querySelector('#edit-assignment-weight').value),scrollY=window.scrollY;if(!reviewerName)return toast('请填写评价人姓名');if(!Number.isFinite(weightPercent)||weightPercent<1||weightPercent>100)return toast('权重必须在 1% 至 100% 之间');button.disabled=true;button.textContent='正在保存…';try{await api(`/api/admin/assignments/${id}/update`,{method:'POST',body:JSON.stringify({reviewerName,weight:weightPercent/100})});mask.remove();toast('权重已修改，原始评分已保留');await renderAssignments();window.scrollTo(0,scrollY)}catch(e){button.disabled=false;button.textContent='保存修改';toast(e.message)}}
async function removeAssignment(id){const item=window.assignmentData.assignments.find(x=>x.id===id);if(!item||!confirm(`确定删除“${item.submission_name}—${item.reviewer_name}”的评价关系吗？\n该评价人对此人的草稿和评分也会删除。`))return;try{await api(`/api/admin/assignments/${id}/delete`,{method:'POST',body:'{}'});toast('评价关系已删除');renderAssignments()}catch(e){toast(e.message)}}
async function saveAssignment(){if(!updateAssignmentWeightNotice(true))return;const submissionId=document.querySelector('#assignment-submission').value,reviewerName=document.querySelector('#assignment-reviewer').value.trim(),contact=(window.assignmentContacts||[]).find(x=>x.name===reviewerName),reviewerUserId=contact?.userId||'',weight=Number(document.querySelector('#assignment-weight').value)/100;selectedAssignmentSubmissionId=submissionId;try{await api('/api/admin/assignments',{method:'POST',body:JSON.stringify({submissionId,reviewerName,reviewerUserId,weight})});toast('匹配关系已保存，可继续添加评委');renderAssignments()}catch(e){toast(e.message)}}
async function pushAssignment(id){try{const result=await api(`/api/admin/assignments/${id}/push`,{method:'POST',body:'{}'});await navigator.clipboard.writeText(location.origin+result.reviewPath);toast(result.notification?.status==='模拟成功'?'评审入口已生成，钉钉模拟提醒已记录':'评审入口已生成并复制');renderAssignments()}catch(e){toast(e.message)}}
