async function showReviewTrace(assignmentId){try{const d=await api(`/api/admin/assignments/${assignmentId}/review-detail`),mask=document.createElement('div');mask.className='drawer-mask';mask.onclick=e=>{if(e.target===mask)mask.remove()};const standard=d.scores.filter(x=>x.section_type!=='bonus'),bonus=d.scores.filter(x=>x.section_type==='bonus');const scoreRows=items=>items.length?items.map(x=>`<tr><td>${esc(x.module_name||x.evaluation_item)}</td><td>${x.score==null?'未评分':Number(x.score).toFixed(1)}</td><td>${x.convertedScore==null?'—':Number(x.convertedScore).toFixed(2)}</td><td>${esc(x.comment||'—')}</td></tr>`).join(''):'<tr><td colspan="4">暂无评分记录</td></tr>';mask.innerHTML=`<aside class="drawer review-trace"><div class="drawer-head"><div><div class="eyebrow">评价痕迹</div><h2>${esc(d.reviewer_name)} → ${esc(d.submission_name)}</h2></div><button class="close" onclick="this.closest('.drawer-mask').remove()">×</button></div><div class="trace-meta"><span>状态：${esc(d.review_status||'未开始')}</span><span>评价人权重：${(Number(d.weight)*100).toFixed(0)}%</span><span>最后保存：${esc(d.updated_at||'—')}</span></div><h3>行为标准评分</h3><table class="table"><thead><tr><th>维度</th><th>原始分</th><th>折算分</th><th>单项评价</th></tr></thead><tbody>${scoreRows(standard)}</tbody></table><h3>团队成长贡献</h3><table class="table"><thead><tr><th>维度</th><th>加分</th><th>计入分</th><th>说明</th></tr></thead><tbody>${scoreRows(bonus)}</tbody></table><section class="trace-qualitative"><h3>定性评价</h3><label>优势</label><p>${esc(d.strengths||'未填写')}</p><label>不足与改进</label><p>${esc(d.improvements||'未填写')}</p><label>评估意见</label><p><strong>${esc(d.opinion||'未选择')}</strong>${d.opinion_note?` · ${esc(d.opinion_note)}`:''}</p></section></aside>`;document.body.append(mask)}catch(e){toast(e.message)}}
function renderImport(){
  document.body.classList.remove('review-mode','assigned-review-mode');
  title.textContent='批量导入'; previewBatch=null;
  app.innerHTML=`<div class="content"><div id="import-stage"><div class="dropzone" id="dropzone"><div class="drop-icon">⇧</div><h3>拖入学员认证 Excel</h3><p>支持多个 .xlsx；文件逐个流式上传并在后台排队解析，单文件默认上限 300 MB</p><input id="file-input" type="file" accept=".xlsx" multiple hidden/></div><div id="files" class="file-list"></div><div class="actions"><button class="secondary" onclick="recoverLatestImport()">恢复最近解析结果</button><button class="primary" id="parse" disabled>上传并开始解析</button></div></div></div>`;
  const dz=document.querySelector('#dropzone'), input=document.querySelector('#file-input'); dz.onclick=()=>input.click(); input.onchange=()=>addFiles([...input.files]); ['dragenter','dragover'].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.add('drag')})); ['dragleave','drop'].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.remove('drag')})); dz.addEventListener('drop',e=>addFiles([...e.dataTransfer.files])); document.querySelector('#parse').onclick=parseFiles; renderFiles();
}
async function recoverLatestImport(){try{const job=await api('/api/import/jobs/latest');if(job.status!=='已完成')return toast(`最近任务状态：${job.status} ${job.completed}/${job.total}`);previewBatch=job.result;renderPreview();toast(`已恢复 ${job.total} 个文件的解析结果`)}catch(e){toast(e.message)}}
function addFiles(files){ const accepted=files.filter(x=>x.name.toLowerCase().endsWith('.xlsx')); selectedFiles=[...selectedFiles,...accepted].filter((f,i,a)=>a.findIndex(x=>x.name===f.name&&x.size===f.size)===i); renderFiles(); }
function renderFiles(){ const box=document.querySelector('#files'); if(!box)return; box.innerHTML=selectedFiles.map((f,i)=>`<div class="file-row"><div class="file-icon">X</div><div><strong>${esc(f.name)}</strong><div class="subtle">${(f.size/1024).toFixed(1)} KB</div></div><button class="ghost" onclick="removeFile(${i})">移除</button></div>`).join(''); document.querySelector('#parse').disabled=!selectedFiles.length; }
function removeFile(i){selectedFiles.splice(i,1);renderFiles()}
async function parseFiles(){
  const stage=document.querySelector('#import-stage'); stage.innerHTML='<div class="panel loading"><div class="spinner"></div>正在解析单元格、合并区域和嵌入图片…</div>';
  try{
    const batch=await api('/api/import/batch',{method:'POST',body:'{}'});
    for(let i=0;i<selectedFiles.length;i++){
      stage.innerHTML=`<div class="panel loading"><div class="spinner"></div>正在上传并解析 ${i+1}/${selectedFiles.length}：${esc(selectedFiles[i].name)}</div>`;
      const response=await fetch('/api/import/upload',{method:'POST',headers:{'X-Batch-Id':batch.batchId,'X-Filename':encodeURIComponent(selectedFiles[i].name),'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'},body:selectedFiles[i]});
      if(!response.ok){const problem=await response.json();throw new Error(problem.error||'文件上传失败')}
    }
    let job=await api('/api/import/parse',{method:'POST',body:JSON.stringify({batchId:batch.batchId})});
    while(job.status!=='已完成'){
      if(job.status==='任务异常')throw new Error(job.error||'后台解析任务异常');
      stage.innerHTML=`<div class="panel parse-progress"><div class="spinner"></div><div><h3>后台解析中 ${job.completed}/${job.total}</h3><p>${esc(job.currentFile||'正在准备解析任务')}</p><div class="progress-track"><i style="width:${job.total?job.completed/job.total*100:0}%"></i></div><small>可以逐个隔离失败文件，不会因为某一个复杂 Excel 中断整批。</small></div></div>`;
      await new Promise(resolve=>setTimeout(resolve,700));job=await api(`/api/import/jobs/${batch.batchId}`);
    }
    previewBatch=job.result;renderPreview();
  }catch(e){stage.innerHTML=`<div class="panel empty"><h3>解析失败</h3><p>${esc(e.message)}</p><button class="secondary" onclick="renderImport()">重新选择</button></div>`;}
}
function renderPreview(){
  const valid=previewBatch.items.filter(x=>!x.errors?.length).length; const warn=previewBatch.items.filter(x=>x.warnings?.length).length; const stage=document.querySelector('#import-stage');
  stage.innerHTML=`<div class="batch-summary"><strong>${previewBatch.items.length} 个文件</strong><span class="badge-ok">${valid} 个可导入</span><span class="badge-warn">${warn} 个有提醒</span></div>${previewBatch.items.map((x,i)=>previewCard(x,i)).join('')}<div class="actions"><button class="secondary" onclick="renderImport()">重新选择</button><button class="primary" id="confirm">确认导入</button></div>`;
  document.querySelector('#confirm').onclick=confirmImport;
}
function previewCard(x,i){ const hasError=x.errors?.length,p=x.package||{},embedded=p.embeddedObjects||[]; return `<article class="preview-card"><div class="preview-head"><input type="checkbox" class="preview-check" data-index="${i}" ${!hasError?'checked':''} ${hasError?'disabled':''}/><div class="file-icon">X</div><div class="preview-title"><strong>${esc(x.fileName)}</strong><div class="preview-meta"><span>${esc(x.name||'未识别学员')}</span><span>${esc(x.level||'未识别职级')}</span><span>${x.modules?.length||0} 个模块</span><span>${x.attachments?.length||0} 份表内附件</span><span>${(Number(p.fileSize||0)/1024/1024).toFixed(1)} MB · ${esc(p.risk||'常规')}</span></div></div><span class="${hasError?'badge-error':embedded.length?'badge-warn':x.warnings?.length?'badge-warn':'badge-ok'}">${hasError?'无法导入':embedded.length?`匹配 ${embedded.filter(e=>e.matched).length}/${embedded.length} 个嵌入对象`:x.warnings?.length?'需要确认':'校验通过'}</span></div>${[...(x.errors||[]).map(m=>`<div class="message error">错误：${esc(m)}</div>`),...(x.warnings||[]).map(m=>`<div class="message warn">提醒：${esc(m)}</div>`)].length?`<div class="messages">${(x.errors||[]).map(m=>`<div class="message error">错误：${esc(m)}</div>`).join('')}${(x.warnings||[]).map(m=>`<div class="message warn">提醒：${esc(m)}</div>`).join('')}</div>`:''}${embedded.length?`<div class="embedded-warning"><strong>嵌入附件位置匹配</strong>${embedded.map(e=>`<span>${e.matched?`第${e.sourceRow}行 · ${esc(e.projectName)} · ${esc(e.materialName)} · ${esc(e.storagePath)}`:`未匹配 · ${esc(e.kind)} · ${esc(e.name)}`}</span>`).join('')}</div>`:''}<div class="preview-details"><div><strong>工作模块</strong><ul class="mini-list">${(x.modules||[]).slice(0,6).map(m=>`<li>${esc(m.moduleName||m.evaluationItem||'未命名')} ${m.weight!=null?`· ${formatWeight(m.weight)}`:''}</li>`).join('')}</ul></div><div><strong>附件材料</strong><ul class="mini-list">${(x.attachments||[]).slice(0,6).map(a=>`<li>附件${esc(a.serial)} · ${esc(a.materialName||'未命名')}${a.imageFile?' · 含截图':''}</li>`).join('')}</ul></div></div></article>`; }
async function confirmImport(){ const indexes=[...document.querySelectorAll('.preview-check:checked')].map(x=>Number(x.dataset.index)); if(!indexes.length)return toast('请至少选择一个可导入文件'); const btn=document.querySelector('#confirm');btn.disabled=true;btn.textContent='正在入库…';try{const result=await api('/api/import/confirm',{method:'POST',body:JSON.stringify({batchId:previewBatch.batchId,indexes})});selectedFiles=[];toast(`已导入 ${result.created.length} 位学员`);setView('dashboard')}catch(e){toast(e.message);btn.disabled=false;btn.textContent='确认导入'}}
async function openSubmission(id,reviewToken=''){
  document.body.classList.add('review-mode'); document.body.classList.toggle('assigned-review-mode',!!reviewToken||publicReviewMode); app.innerHTML='<div class="content loading"><div class="spinner"></div>加载学员材料…</div>'; const detailUrl=reviewToken?`/api/review/${reviewToken}`:publicReviewMode?`/api/public/submissions/${id}`:`/api/submissions/${id}`; const d=await api(detailUrl), s=d.submission; window.currentDetail=d; window.currentReviewToken=reviewToken;
  const isMatrix=!!applicationStandardSnapshot(s).matrix;
  app.innerHTML=`<div class="content review-content"><button class="ghost back-button" onclick="renderDashboard()">← 返回认证材料</button><div class="review-layout"><aside class="review-nav">${reviewDimensionNavigation(d)}${unlinkedReviewAttachments(d).length?'<button class="nav-section nav-primary" onclick="scrollToSection(\'attachments\')">补充附件</button>':''}<button class="nav-section nav-primary" onclick="scrollToSection('qualitative')">总体评价</button></aside><div><section class="overview-card sticky-overview"><div class="applicant-info"><div class="eyebrow">认证申请</div><h2>${esc(s.name)}</h2><div class="overview-meta"><span>申报 ${esc(s.level)}</span><span>${esc(s.category)}</span><span>${esc(s.applied_at||'未填写日期')}</span></div></div><div class="live-score"><small>评委总分</small><strong id="live-total">0.00</strong><div><span>${isMatrix?'各维度评分':'行为标准'} <b id="behavior-total">0.00</b></span><i>+</i><span>成长贡献 <b id="bonus-total">0.00</b></span></div><button onclick="toggleScoreBreakdown()">查看折算明细</button></div></section><section class="score-breakdown" id="score-breakdown"><div class="breakdown-head"><strong>实时折算明细</strong><span>${isMatrix?'各维度普通评分项':'行为标准'}：(原始分 ÷ 5) × 100 × 权重；成长贡献：原始分直接相加</span></div><div id="breakdown-rows"></div></section><div class="reviewer-bar"><label>当前评委</label><input id="reviewer-name" value="${esc(d.review?.reviewer_name||'')}" placeholder="请输入评委姓名"/><span class="subtle">${isMatrix?'各维度普通评分子项':'行为标准'}每项满分 5 分；成果贡献每项最多加 2 分</span></div>${reviewDimensionsHtml(d)}${reviewUnlinkedAttachmentsHtml(d)}${qualitativeCard(d.review)}<div class="savebar"><span class="subtle">评分和评价可先保存为草稿</span><div><button class="secondary" onclick="saveReview(false)">保存草稿</button><button class="primary" onclick="saveReview(true)">提交本次评审</button></div></div></div></div></div>`;
  if(currentActor?.role==='管理员'&&!reviewToken&&!publicReviewMode&&!d.evidenceTask){document.querySelector('#attachments').hidden=false;document.querySelector('#attachments').insertAdjacentHTML('afterbegin',`<div class="manual-attachment-bar"><div><strong>补充附件</strong><small>支持 Word、PPT、Excel、PDF、图片或 ZIP，可一次选择多个文件</small></div><input id="manual-attachment-input" type="file" multiple hidden/><button class="secondary" onclick="document.querySelector('#manual-attachment-input').click()">上传附件/附件包</button></div>`);document.querySelector('#manual-attachment-input').onchange=e=>uploadSupplementalAttachments(s.id,[...e.target.files])}
  if(reviewToken){const reviewerInput=document.querySelector('#reviewer-name');reviewerInput.value=d.assignment.reviewerName;reviewerInput.readOnly=true}
  document.querySelectorAll('.module-score').forEach(input=>{input.closest('.score-input').insertAdjacentHTML('afterend',`<span class="score-error" data-score-error="${input.dataset.module}" aria-live="polite"></span>`);input.addEventListener('input',()=>{validateScoreInput(input);updateScoreSummary()});input.addEventListener('blur',()=>validateScoreInput(input));validateScoreInput(input)});
  if(applicationStandardSnapshot(s).matrix)setupMatrixReview(d);
  if(d.evidenceTask)setupEvidenceAdmin(d);
  secureEvidenceMedia();
  updateScoreSummary();
}
function moduleCard(m){ const linked=(window.currentDetail?.attachments||[]).filter(a=>(m.attachment_ids||[]).includes(a.id)); const saved=(window.currentDetail?.scores||[]).find(x=>x.module_id===m.id)||{}; const isBonus=m.section_type==='bonus', max=isBonus?2:5; return `<article class="module-card ${isBonus?'bonus-card':''}" id="m-${m.id}" ${m.section_type==='reference'?`data-reference-module="${m.id}"`:''}><div class="module-header"><h3>${esc(m.module_name||m.evaluation_item)}</h3><div><span class="tag">${isBonus?`${esc(m.evaluation_item)} · 额外加分`:`${esc(m.evaluation_item||'行为标准')} · 权重 ${formatWeight(m.weight)}`}</span>${m.self_score?` <span class="tag green">自评 ${esc(m.self_score)}</span>`:''}</div></div><div class="module-grid"><div class="module-body">${m.standard?`<div class="field-label">职级定义标准</div><div class="standard">${esc(m.standard)}</div>`:''}<div class="field-label">工作成果与行为举证</div><div class="evidence evidence-current-text" id="e-${m.id}">${esc(m.evidence||'未填写')}</div>${(m.evidence||'').length>180?`<button class="text-button" onclick="toggleEvidence('${m.id}',this)">展开全文</button>`:''}${reviewAttachmentsHtml(linked)}</div><aside class="score-panel"><div class="field-label">${isBonus?'评委加分':'评委评分'}</div><div class="score-input"><input aria-label="${esc(m.module_name||m.evaluation_item)}评分" class="module-score" data-module="${m.id}" data-type="${m.section_type}" data-weight="${m.weight??0}" data-name="${esc(m.module_name)}" type="number" min="0" max="${max}" step="0.5" value="${saved.score??''}" placeholder="—"/><span>/ ${max}</span></div>${isBonus?'':`<div class="conversion-result">折算得分 <strong data-converted="${m.id}">0.00</strong></div><div class="field-label">单项评价</div><textarea aria-label="${esc(m.module_name||m.evaluation_item)}单项评价" class="module-comment" data-module="${m.id}" placeholder="记录判断依据或改进建议">${esc(saved.comment||'')}</textarea>`}</aside></div></article>`; }
function qualitativeCard(review){return `<section class="qualitative" id="qualitative"><h2 class="section-title">评委意见及总体评价</h2><div class="form-field"><label>优势</label><textarea id="strengths" placeholder="填写该学员表现突出的能力、成果或行为">${esc(review?.strengths||'')}</textarea></div><div class="form-field"><label>不足或待改进项</label><textarea id="improvements" placeholder="填写能力差距和具体改进建议">${esc(review?.improvements||'')}</textarea></div><div class="form-field"><label>评估意见</label><div class="opinion-options">${['通过','不通过','其他'].map(x=>`<label><input type="radio" name="opinion" value="${x}" ${review?.opinion===x?'checked':''}/> ${x}</label>`).join('')}</div><textarea id="opinion-note" placeholder="补充说明评估结论">${esc(review?.opinion_note||'')}</textarea></div></section>`}
async function saveReview(submit){const invalid=[...document.querySelectorAll('.module-score')].filter(input=>!validateScoreInput(input));if(invalid.length){invalid[0].focus();return toast('请先修正标红的评分');}const reviewerName=document.querySelector('#reviewer-name').value.trim();if(!reviewerName)return toast('请先填写评委姓名');const moduleScores=[...document.querySelectorAll('.module-score')].map(input=>({moduleId:input.dataset.module,score:input.value,comment:document.querySelector(`.module-comment[data-module="${input.dataset.module}"]`)?.value||''}));const payload={reviewerName,moduleScores,strengths:document.querySelector('#strengths').value,improvements:document.querySelector('#improvements').value,opinion:document.querySelector('input[name="opinion"]:checked')?.value||'',opinionNote:document.querySelector('#opinion-note').value,submit};const endpoint=window.currentReviewToken?`/api/review/${window.currentReviewToken}/save`:publicReviewMode?`/api/public/submissions/${window.currentDetail.submission.id}/review`:`/api/submissions/${window.currentDetail.submission.id}/review`;try{const result=await api(endpoint,{method:'POST',body:JSON.stringify(payload)});toast(`${result.status==='已提交'?'评审已提交':'草稿已保存'} · 总分 ${Number(result.scoreSummary.total).toFixed(2)}`);if(submit&&publicReviewMode)setTimeout(()=>renderPublicReviewThanks(result),700)}catch(e){toast(e.message)}}
function validateScoreInput(input){const value=input.value.trim(),max=Number(input.max),error=document.querySelector(`[data-score-error="${input.dataset.module}"]`);let message='';if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>max))message=`请输入 0–${max} 分`;input.classList.toggle('invalid',!!message);input.setAttribute('aria-invalid',message?'true':'false');if(error)error.textContent=message;return !message}
function updateScoreSummary(){let behavior=0,bonus=0;const rows=[];document.querySelectorAll('.module-score').forEach(input=>{const valid=validateScoreInput(input);let raw=valid?Math.max(0,Number(input.value)||0):0,converted;if(input.dataset.type==='bonus'){converted=raw;bonus+=raw;rows.push(`<div><span>${esc(input.dataset.name)}</span><code>${valid?`${raw.toFixed(1)} 分直接计入`:'分数无效，暂不计入'}</code><strong>+${converted.toFixed(2)}</strong></div>`)}else{const weight=Number(input.dataset.weight)||0;converted=raw/5*100*weight;behavior+=converted;rows.push(`<div><span>${esc(input.dataset.name)}</span><code>${valid?`(${raw.toFixed(1)} ÷ 5) × 100 × ${(weight*100).toFixed(0)}%`:'分数无效，暂不计入'}</code><strong>${converted.toFixed(2)}</strong></div>`);const cell=document.querySelector(`[data-converted="${input.dataset.module}"]`);if(cell)cell.textContent=converted.toFixed(2)}});const configured=reviewWeightsReady(window.currentDetail);document.querySelector('#behavior-total').textContent=configured?behavior.toFixed(2):'待配置';document.querySelector('#bonus-total').textContent=bonus.toFixed(2);document.querySelector('#live-total').textContent=configured?(behavior+bonus).toFixed(2):'待配置';document.querySelector('#breakdown-rows').innerHTML=rows.join('')}
function toggleScoreBreakdown(){document.querySelector('#score-breakdown').classList.toggle('open')}
function scrollToSection(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function toggleAttachments(){const content=document.querySelector('#attachment-content'),open=content.classList.toggle('open');document.querySelector('#attachment-toggle-text').textContent=open?'收起附件⌃':`展开 ${window.currentDetail.attachments.length} 份附件⌄`}
function toggleEvidence(id,btn){const el=document.querySelector(`#e-${id}`);el.classList.toggle('expanded');btn.textContent=el.classList.contains('expanded')?'收起':'展开全文'}
function attachmentTable(items){return `<div class="panel attachment-table"><table class="table"><thead><tr><th>序号</th><th>对应项目</th><th>材料名称</th><th>材料/地址</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td>${esc(a.serial)}</td><td>${esc(a.project_name)}</td><td>${esc(a.material_name)}</td><td class="path"><div>${esc(a.storage_path)}</div>${a.link_url?`<a href="${esc(a.link_url)}" target="_blank" rel="noopener">${esc(a.link_url)}</a>`:''}</td><td><button class="secondary compact" onclick="showAttachment('${a.id}')">查看</button></td></tr>`).join('')}</tbody></table></div>`}
function showAttachment(id){ const a=window.currentDetail.attachments.find(x=>x.id===id); const mask=document.createElement('div');mask.className='drawer-mask';mask.onclick=e=>{if(e.target===mask)mask.remove()};mask.innerHTML=`<aside class="drawer"><div class="drawer-head"><div><div class="eyebrow">附件 ${esc(a.serial)}</div><h2>${esc(a.material_name)}</h2></div><button class="close" onclick="this.closest('.drawer-mask').remove()">×</button></div><div class="detail-row"><label>对应项目</label><strong>${esc(a.project_name||'—')}</strong></div><div class="detail-row"><label>材料名称/存放说明</label><div class="path-box">${esc(a.storage_path||'未填写')}</div><button class="text-button" onclick="copyPath('${esc(a.id)}')">复制说明</button></div>${a.link_url?`<div class="detail-row"><label>访问地址</label><div class="path-box">${esc(a.link_url)}</div><a class="text-button" href="${esc(a.link_url)}" target="_blank" rel="noopener">打开地址</a></div>`:''}${a.uploaded_file_path?`<div class="detail-row"><label>附件文件</label><a class="primary attachment-download" href="${esc(reviewMediaPath(a.uploaded_file_path,'download'))}" download>下载或打开 ${esc(a.storage_path||a.material_name)}</a></div>`:''}<div class="detail-row attachment-preview"><label>材料预览</label>${reviewAttachmentPreviewHtml(a)}</div></aside>`;document.body.append(mask);secureEvidenceMedia()}
async function uploadSupplementalAttachments(submissionId,files){if(!files.length)return;const bar=document.querySelector('.manual-attachment-bar');for(let i=0;i<files.length;i++){bar.querySelector('small').textContent=`正在上传 ${i+1}/${files.length}：${files[i].name}`;const response=await fetch(`/api/admin/submissions/${submissionId}/attachments/upload`,{method:'POST',headers:{'X-Filename':encodeURIComponent(files[i].name),'X-Project-Name':encodeURIComponent('管理员补充附件'),'Content-Type':'application/octet-stream'},body:files[i]});if(!response.ok){const problem=await response.json();return toast(problem.error||`${files[i].name} 上传失败`)}}toast(`已上传 ${files.length} 个补充附件`);openSubmission(submissionId)}
